begin;
do $$
declare c uuid;v uuid;d uuid;notice uuid;r jsonb;x jsonb;other uuid;
begin
 insert into public.contacts(phone,ai_disclosure_shown) values('+34999000991',true) returning id into c;
 insert into public.conversations(contact_id,channel) values(c,'whatsapp') returning id into v;
 insert into public.messages(conversation_id,direction,body) values(v,'inbound','Consulta ficticia');
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,delivery_type,payload) values(c,v,'whatsapp','freeform','{"prompt_version":"bf26-v2","body":"Respuesta exacta del agente"}') returning id into d;
 if public.olivia_dispatcher_claim(d) is not null then raise exception 'Pause bypassed'; end if;
 update public.olivia_config set value=value||'{"whatsapp_outbound_enabled":true,"whatsapp_phone_number_id":"test-sender"}' where key='bf2026';
 r:=public.olivia_dispatcher_claim(d);
 if r->>'body'<>'Respuesta exacta del agente' or r->>'dispatch_id'<>d::text then raise exception 'Decision changed or incorrect targeted claim'; end if;
 if public.olivia_dispatcher_claim(d) is not null then raise exception 'Duplicate claim'; end if;
 if public.olivia_dispatcher_start(r) is null or public.olivia_dispatcher_start(r) is not null then raise exception 'Provider attempt lease failed'; end if;
 perform public.olivia_dispatcher_finish(jsonb_build_object('dispatch_id',d,'external_id',null,'error','Rate limited','retry_safe',true));
 if (select status<>'pending' or scheduled_for<=now() or provider_attempt_at is not null from public.outbound_dispatches where id=d) then raise exception 'Retry not deferred'; end if;
 update public.outbound_dispatches set scheduled_for=now() where id=d;
 r:=public.olivia_dispatcher_claim(d);perform public.olivia_dispatcher_start(r);
 perform public.olivia_dispatcher_finish(jsonb_build_object('dispatch_id',d,'external_id','fake-provider-id'));
 if (select status from public.outbound_dispatches where id=d)<>'sent' then raise exception 'Receipt not persisted'; end if;
 perform public.olivia_dispatcher_finish(jsonb_build_object('dispatch_id',d,'error','late failure'));
 if (select status from public.outbound_dispatches where id=d)<>'sent' then raise exception 'Late failure overwrote receipt'; end if;
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,payload,status,claimed_at) values(c,v,'whatsapp','{"prompt_version":"bf26-v2","body":"Unsent"}','processing',now()-interval '11 minutes') returning id into d;
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,payload,status,claimed_at,provider_attempt_at) values(c,v,'whatsapp','{"prompt_version":"bf26-v2","body":"Unknown"}','processing',now()-interval '11 minutes',now()-interval '11 minutes') returning id into other;
 perform public.olivia_dispatcher_recover();
 if (select status from public.outbound_dispatches where id=d)<>'pending' or (select status from public.outbound_dispatches where id=other)<>'failed' then raise exception 'Unsafe stale recovery'; end if;
 update public.contacts set ai_disclosure_shown=false,ai_disclosure_dispatch_id=null where id=c;
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,payload) values(c,v,'whatsapp','{"prompt_version":"bf26-v2","body":"First reply"}') returning id into d;
 r:=public.olivia_dispatcher_claim(d);notice:=(r->>'dispatch_id')::uuid;
 if r->>'kind'<>'ai_disclosure' or notice=d then raise exception 'Notice dependency skipped'; end if;
 if public.olivia_claim_customer_dispatch(d) is not null then raise exception 'Reply sent before disclosure'; end if;
 perform public.olivia_dispatcher_start(r);x:=public.olivia_dispatcher_finish(jsonb_build_object('dispatch_id',notice,'external_id','fake-notice-id','processed_count',0));
 if x->>'dispatch_id'<>d::text or (x->>'processed_count')::integer<>1 then raise exception 'Disclosure continuation lost'; end if;
 r:=public.olivia_dispatcher_claim(d);if r->>'body'<>'First reply' then raise exception 'Reply did not follow notice'; end if;
 perform public.olivia_dispatcher_finish(jsonb_build_object('dispatch_id',d,'external_id','fake-reply-id'));
 update public.conversations set handoff_status='pending_human' where id=v;
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,payload) values(c,v,'whatsapp','{"prompt_version":"bf26-v2","kind":"handoff_acknowledgement","body":"Aviso al equipo"}') returning id into d;
 if public.olivia_dispatcher_claim(d) is null then raise exception 'Handoff acknowledgement blocked'; end if;
 update public.conversations set handoff_status='bot' where id=v;
 update public.contacts set ai_disclosure_shown=false,ai_disclosure_dispatch_id=null where id=c;
 insert into public.outbound_dispatches(contact_id,conversation_id,channel,payload) values(c,v,'whatsapp','{"prompt_version":"bf26-v2","body":"New test"}') returning id into d;
 select (payload->>'ai_disclosure_dispatch_id')::uuid into notice from public.outbound_dispatches where id=d;
 update public.outbound_dispatches set status='cancelled' where id=notice;
 perform public.olivia_dispatcher_repair_disclosures();
 if (select payload->>'ai_disclosure_dispatch_id' from public.outbound_dispatches where id=d)=notice::text then raise exception 'Cancelled dependency not repaired'; end if;
end;$$;
rollback;
select 'PASS: targeted claim, master pause, exact agent text, exclusive leases, deferred throttling retry, provider receipts, ambiguous recovery and disclosure continuation.' as result;
